The addon defines two operators: one to apply custom brush settings with proper clamping and one to restore the previous settings. The original values are saved in a scene‑level dictionary so they survive the first operator call and can be restored later. Edge cases (no active sculpt brush or wrong mode) are reported as `CANCELLED` with an informative message.  

```python
import bpy

# -------------------------------------------------------------------
# Helper to clamp values to the ranges defined in the reference.
# -------------------------------------------------------------------
def _clamp(value, min_val, max_val):
    return max(min_val, min(max_val, value))

# -------------------------------------------------------------------
# Operator: Apply custom brush settings (smooth_stroke_radius,
# area_radius_factor, density) with clamping.
# -------------------------------------------------------------------
class OBJECT_OT_apply_custom_brush(bpy.types.Operator):
    bl_idname = "object.apply_custom_brush"
    bl_label = "Apply Custom Brush Settings"
    bl_description = "Set brush properties with safe clamping and store originals"

    smooth_radius: bpy.props.IntProperty(name="Smooth Stroke Radius", default=75)
    area_factor: bpy.props.FloatProperty(name="Area Radius Factor", default=0.5)
    density: bpy.props.FloatProperty(name="Density", default=0.0)

    def execute(self, context):
        # Ensure we are in Sculpt mode and a brush exists.
        obj = context.object
        if not obj or obj.type != 'MESH':
            self.report({'ERROR'}, "Active object must be a mesh")
            return {'CANCELLED'}

        if obj.mode != 'SCULPT':
            self.report({'ERROR'}, "Object must be in Sculpt mode")
            return {'CANCELLED'}

        brush = context.tool_settings.sculpt.brush
        if not brush:
            self.report({'ERROR'}, "No active sculpt brush")
            return {'CANCELLED'}

        # Store original values on the scene (once per session).
        scene = context.scene
        if "brush_originals" not in scene:
            scene["brush_originals"] = {}
        scene["brush_originals"] = {
            "smooth_stroke_radius": brush.smooth_stroke_radius,
            "area_radius_factor": brush.area_radius_factor,
            "density": brush.density,
        }

        # Clamp to valid ranges (reference limits).
        brush.smooth_stroke_radius = _clamp(self.smooth_radius, 10, 200)
        brush.area_radius_factor = _clamp(self.area_factor, 0.0, 2.0)
        brush.density = _clamp(self.density, 0.0, 1.0)

        self.report({'INFO'}, "Custom brush settings applied")
        return {'FINISHED'}

# -------------------------------------------------------------------
# Operator: Restore the previously saved brush settings.
# -------------------------------------------------------------------
class OBJECT_OT_restore_brush(bpy.types.Operator):
    bl_idname = "object.restore_brush"
    bl_label = "Restore Brush Settings"
    bl_description = "Restore brush properties saved by the apply operator"

    def execute(self, context):
        obj = context.object
        if not obj or obj.type != 'MESH':
            self.report({'ERROR'}, "Active object must be a mesh")
            return {'CANCELLED'}

        if obj.mode != 'SCULPT':
            self.report({'ERROR'}, "Object must be in Sculpt mode")
            return {'CANCELLED'}

        brush = context.tool_settings.sculpt.brush
        if not brush:
            self.report({'ERROR'}, "No active sculpt brush")
            return {'CANCELLED'}

        scene = context.scene
        originals = scene.get("brush_originals")
        if not originals:
            self.report({'WARNING'}, "No stored brush settings to restore")
            return {'CANCELLED'}

        brush.smooth_stroke_radius = originals["smooth_stroke_radius"]
        brush.area_radius_factor = originals["area_radius_factor"]
        brush.density = originals["density"]

        # Clean up stored data.
        del scene["brush_originals"]
        self.report({'INFO'}, "Brush settings restored")
        return {'FINISHED'}

# -------------------------------------------------------------------
# Registration
# -------------------------------------------------------------------
def register():
    bpy.utils.register_class(OBJECT_OT_apply_custom_brush)
    bpy.utils.register_class(OBJECT_OT_restore_brush)

def unregister():
    bpy.utils.unregister_class(OBJECT_OT_apply_custom_brush)
    bpy.utils.unregister_class(OBJECT_OT_restore_brush)

if __name__ == "__main__":
    register()
```

