    # Clamp the range to the valid [0, 120] range as per API constraints
    gp_data.ghost_after_range = max(0, min(120, after_range))

    # Set the keyframe type for onion skinning filtering
    if keyframe_type in {'ALL', 'KEYFRAME', 'BREAKDOWN', 'EXTREME'}:
        gp_data.onion_keyframe_type = keyframe_type

def get_layer_group_count(gp_data: bpy.types.GreasePencil) -> int:
    # layer_groups is a collection, return its length
    return len(gp_data.layer_groups)
