import bpy
from bpy.props import IntProperty, FloatProperty

def retime_keyframes(action, start, end, factor):
    """Efficiently retime keyframes within [start, end] by factor."""
    for fcurve in action.fcurves:
        for kp in fcurve.keyframe_points:
            frame = kp.co.x
            if start <= frame <= end:
                kp.co.x = start + (frame - start) * factor
    # Update handles after bulk edit
    action.update()

class OBJECT_OT_RetimeKeys(bpy.types.Operator):
    """Retime selected object's keyframes"""
    bl_idname = "object.retime_keys"
    bl_label = "Retime Keys"
    bl_options = {'REGISTER', 'UNDO'}

    start_frame: IntProperty(name="Start Frame", default=1)
    end_frame: IntProperty(name="End Frame", default=250)
    factor: FloatProperty(name="Factor", default=1.0)

    @classmethod
    def poll(cls, context):
        obj = context.active_object
        return obj and obj.animation_data and obj.animation_data.action

    def execute(self, context):
        action = context.active_object.animation_data.action
        retime_keyframes(action, self.start_frame, self.end_frame, self.factor)
        return {'FINISHED'}

    def invoke(self, context, event):
        wm = context.window_manager
        return wm.invoke_props_dialog(self)

class VIEW3D_PT_RetimePanel(bpy.types.Panel):
    bl_label = "Retiming Keys"
    bl_idname = "VIEW3D_PT_retime_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "Retiming"

    def draw(self, context):
        self.layout.operator(OBJECT_OT_RetimeKeys.bl_idname)

classes = (OBJECT_OT_RetimeKeys, VIEW3D_PT_RetimePanel)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
