class VIEW3D_OT_align_camera(bpy.types.Operator):
    bl_idname = "view3d.align_camera_to_view"
    bl_label = "Align Camera to View"

    def execute(self, context):
        # Find the 3D View area to provide the correct context for the operator
        for area in context.screen.areas:
