import bpy

class SimpleNodeGroup(bpy.types.NodeGroup):
    bl_idname = "SimpleNodeGroup"
    bl_label = "Simple Node Group"

    def init(self, context):
        self.nodes.new('NodeGroupInput')
        self.nodes.new('NodeGroupOutput')

