A small addon that adds an operator `node.clean_interface`. The operator works on the active node tree, logs each interface item’s type, position and parent panel, deletes non‑panel items, and returns a report. Edge cases such as a missing interface or a `None` parent are safely handled.

```python
import bpy

bl_info = {
    "name": "Node Interface Cleaner",
    "blender": (5, 0, 0),
    "category": "Node",
}

class NODE_OT_clean_interface(bpy.types.Operator):
    """Remove all non‑panel items from the active node tree interface"""
    bl_idname = "node.clean_interface"
    bl_label = "Clean Node Interface"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        node_tree = getattr(context.space_data, "node_tree", None)
        if not node_tree or not hasattr(node_tree, "interface"):
            self.report({'WARNING'}, "Active space has no node tree with an interface")
            return {'CANCELLED'}

        interface = node_tree.interface
        if not hasattr(interface, "items"):
            self.report({'WARNING'}, "Node tree interface has no items collection")
            return {'CANCELLED'}

        removed = []
        # Iterate over a copy because we will modify the collection
        for item in list(interface.items):
            # Read‑only properties from the reference
            itype = item.item_type          # e.g. 'PANEL' or other
            pos = item.position
            parent = item.parent

            parent_name = parent.name if parent else "None"
            print(f"[Node Interface] type={itype}, position={pos}, parent={parent_name}")

            if itype != 'PANEL':
                interface.items.remove(item)
                removed.append((itype, pos, parent_name))

        self.report({'INFO'}, f"Removed {len(removed)} non‑panel items")
        # Store the report for possible UI use
        self.removed_items = removed
        return {'FINISHED'}

def menu_func(self, context):
    self.layout.operator(NODE_OT_clean_interface.bl_idname, text="Clean Node Interface")

def register():
    bpy.utils.register_class(NODE_OT_clean_interface)
    bpy.types.NODE_MT_editor_menus.append(menu_func)

def unregister():
    bpy.types.NODE_MT_editor_menus.remove(menu_func)
    bpy.utils.unregister_class(NODE_OT_clean_interface)

if __name__ == "__main__":
    register()
```

