This function modifies the object by adding a Subdivision Surface modifier, creates and assigns a new material, and iterates through the 3D View areas to enable the UI region visibility.

```python
import bpy

def setup_object_and_ui(obj: bpy.types.Object, mat_name: str) -> None:
    # Add Subdivision Surface modifier
    mod = obj.modifiers.new(name="Subdiv", type='SUBSURF')
    mod.levels = 2

    # Create and assign material
    mat = bpy.data.materials.new(name=mat_name)
    if obj.data.materials:
        obj.data.materials[0] = mat
    else:
        obj.data.materials.append(mat)

    # Enable UI region in all 3D View areas
    for area in bpy.context.window.screen.areas:
        if area.type == 'VIEW_3D':
            for space in area.spaces:
                if space.type == 'VIEW_3D':
                    space.show_region_ui = True
